-- Durable Universal Business intelligence artifacts: diagnosis -> opportunity -> recommendation -> priority.
create table if not exists public.business_diagnoses (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.business_profiles(id) on delete cascade, title text not null, problem text not null, symptoms jsonb not null default '[]'::jsonb, root_causes jsonb not null default '[]'::jsonb, impact text not null, confidence numeric not null default 0.5 check (confidence >= 0 and confidence <= 1), signal_ids uuid[] not null default '{}', evidence_ids uuid[] not null default '{}', alternatives jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.business_opportunities (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.business_profiles(id) on delete cascade, title text not null, description text not null, source_diagnosis_id uuid references public.business_diagnoses(id) on delete set null, impact numeric not null check (impact >= 0 and impact <= 100), urgency numeric not null check (urgency >= 0 and urgency <= 100), confidence numeric not null default 0.5 check (confidence >= 0 and confidence <= 1), effort numeric not null check (effort >= 0 and effort <= 100), cost numeric not null check (cost >= 0 and cost <= 100), risk numeric not null check (risk >= 0 and risk <= 100), roi numeric check (roi is null or (roi >= 0 and roi <= 100)), strategic_value numeric not null check (strategic_value >= 0 and strategic_value <= 100), time_to_result_days integer check (time_to_result_days is null or time_to_result_days >= 0), dependencies text[] not null default '{}', expected_outcome text, related_kpis text[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.business_recommendations (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.business_profiles(id) on delete cascade, opportunity_id uuid not null references public.business_opportunities(id) on delete cascade, title text not null, rationale text not null, actions jsonb not null default '[]'::jsonb, expected_outcome text not null, confidence numeric not null default 0.5 check (confidence >= 0 and confidence <= 1), evidence_ids uuid[] not null default '{}', policy_version text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.business_priority_scores (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.business_profiles(id) on delete cascade, opportunity_id uuid not null references public.business_opportunities(id) on delete cascade, score numeric not null check (score >= 0 and score <= 100), rank integer check (rank is null or rank > 0), policy_version text not null, factors jsonb not null default '{}'::jsonb, explanation text not null, created_at timestamptz not null default now(), unique (opportunity_id, policy_version));
create index if not exists business_diagnoses_business_id_idx on public.business_diagnoses(business_id); create index if not exists business_opportunities_business_id_idx on public.business_opportunities(business_id); create index if not exists business_opportunities_diagnosis_idx on public.business_opportunities(source_diagnosis_id); create index if not exists business_recommendations_business_id_idx on public.business_recommendations(business_id); create index if not exists business_recommendations_opportunity_idx on public.business_recommendations(opportunity_id); create index if not exists business_priority_scores_business_id_idx on public.business_priority_scores(business_id); create index if not exists business_priority_scores_opportunity_idx on public.business_priority_scores(opportunity_id);
alter table public.business_diagnoses enable row level security; alter table public.business_opportunities enable row level security; alter table public.business_recommendations enable row level security; alter table public.business_priority_scores enable row level security;
create policy business_diagnoses_select on public.business_diagnoses for select using (exists (select 1 from public.business_profiles bp where bp.id = business_diagnoses.business_id and public.is_org_member(bp.organization_id))); create policy business_diagnoses_insert on public.business_diagnoses for insert with check (exists (select 1 from public.business_profiles bp where bp.id = business_diagnoses.business_id and public.is_org_member(bp.organization_id))); create policy business_diagnoses_update on public.business_diagnoses for update using (exists (select 1 from public.business_profiles bp where bp.id = business_diagnoses.business_id and public.is_org_member(bp.organization_id))) with check (exists (select 1 from public.business_profiles bp where bp.id = business_diagnoses.business_id and public.is_org_member(bp.organization_id))); create policy business_diagnoses_delete on public.business_diagnoses for delete using (exists (select 1 from public.business_profiles bp where bp.id = business_diagnoses.business_id and public.is_org_member(bp.organization_id)));
create policy business_opportunities_select on public.business_opportunities for select using (exists (select 1 from public.business_profiles bp where bp.id = business_opportunities.business_id and public.is_org_member(bp.organization_id))); create policy business_opportunities_insert on public.business_opportunities for insert with check (exists (select 1 from public.business_profiles bp where bp.id = business_opportunities.business_id and public.is_org_member(bp.organization_id))); create policy business_opportunities_update on public.business_opportunities for update using (exists (select 1 from public.business_profiles bp where bp.id = business_opportunities.business_id and public.is_org_member(bp.organization_id))) with check (exists (select 1 from public.business_profiles bp where bp.id = business_opportunities.business_id and public.is_org_member(bp.organization_id))); create policy business_opportunities_delete on public.business_opportunities for delete using (exists (select 1 from public.business_profiles bp where bp.id = business_opportunities.business_id and public.is_org_member(bp.organization_id)));
create policy business_recommendations_select on public.business_recommendations for select using (exists (select 1 from public.business_profiles bp where bp.id = business_recommendations.business_id and public.is_org_member(bp.organization_id))); create policy business_recommendations_insert on public.business_recommendations for insert with check (exists (select 1 from public.business_profiles bp where bp.id = business_recommendations.business_id and public.is_org_member(bp.organization_id))); create policy business_recommendations_update on public.business_recommendations for update using (exists (select 1 from public.business_profiles bp where bp.id = business_recommendations.business_id and public.is_org_member(bp.organization_id))) with check (exists (select 1 from public.business_profiles bp where bp.id = business_recommendations.business_id and public.is_org_member(bp.organization_id))); create policy business_recommendations_delete on public.business_recommendations for delete using (exists (select 1 from public.business_profiles bp where bp.id = business_recommendations.business_id and public.is_org_member(bp.organization_id)));
create policy business_priority_scores_select on public.business_priority_scores for select using (exists (select 1 from public.business_profiles bp where bp.id = business_priority_scores.business_id and public.is_org_member(bp.organization_id))); create policy business_priority_scores_insert on public.business_priority_scores for insert with check (exists (select 1 from public.business_profiles bp where bp.id = business_priority_scores.business_id and public.is_org_member(bp.organization_id))); create policy business_priority_scores_update on public.business_priority_scores for update using (exists (select 1 from public.business_profiles bp where bp.id = business_priority_scores.business_id and public.is_org_member(bp.organization_id))) with check (exists (select 1 from public.business_profiles bp where bp.id = business_priority_scores.business_id and public.is_org_member(bp.organization_id))); create policy business_priority_scores_delete on public.business_priority_scores for delete using (exists (select 1 from public.business_profiles bp where bp.id = business_priority_scores.business_id and public.is_org_member(bp.organization_id)));
create or replace function public.validate_business_diagnosis_references() returns trigger language plpgsql security definer set search_path = public as $$ begin if exists (select 1 from unnest(coalesce(new.signal_ids, '{}')) as signal_id where not exists (select 1 from public.business_signals s where s.id = signal_id and s.business_id = new.business_id)) then raise exception 'business_diagnoses.signal_ids must reference signals from the same business'; end if; if exists (select 1 from unnest(coalesce(new.evidence_ids, '{}')) as evidence_id where not exists (select 1 from public.business_evidence e where e.id = evidence_id and e.business_id = new.business_id)) then raise exception 'business_diagnoses.evidence_ids must reference evidence from the same business'; end if; return new; end; $$;
create trigger business_diagnosis_reference_scope_trigger before insert or update on public.business_diagnoses for each row execute function public.validate_business_diagnosis_references();
create or replace function public.validate_business_opportunity_scope() returns trigger language plpgsql security definer set search_path = public as $$ begin if new.source_diagnosis_id is not null and not exists (select 1 from public.business_diagnoses d where d.id = new.source_diagnosis_id and d.business_id = new.business_id) then raise exception 'source_diagnosis_id does not belong to business_id'; end if; return new; end; $$;
create trigger business_opportunity_scope_trigger before insert or update on public.business_opportunities for each row execute function public.validate_business_opportunity_scope();
create or replace function public.validate_business_recommendation_scope() returns trigger language plpgsql security definer set search_path = public as $$ begin if not exists (select 1 from public.business_opportunities o where o.id = new.opportunity_id and o.business_id = new.business_id) then raise exception 'opportunity_id does not belong to business_id'; end if; if exists (select 1 from unnest(coalesce(new.evidence_ids, '{}')) as evidence_id where not exists (select 1 from public.business_evidence e where e.id = evidence_id and e.business_id = new.business_id)) then raise exception 'business_recommendations.evidence_ids must reference evidence from the same business'; end if; return new; end; $$;
create trigger business_recommendation_scope_trigger before insert or update on public.business_recommendations for each row execute function public.validate_business_recommendation_scope();
create or replace function public.validate_business_priority_scope() returns trigger language plpgsql security definer set search_path = public as $$ begin if not exists (select 1 from public.business_opportunities o where o.id = new.opportunity_id and o.business_id = new.business_id) then raise exception 'opportunity_id does not belong to business_id'; end if; return new; end; $$;
create trigger business_priority_scope_trigger before insert or update on public.business_priority_scores for each row execute function public.validate_business_priority_scope();
revoke execute on function public.validate_business_diagnosis_references() from public, anon, authenticated; revoke execute on function public.validate_business_opportunity_scope() from public, anon, authenticated; revoke execute on function public.validate_business_recommendation_scope() from public, anon, authenticated; revoke execute on function public.validate_business_priority_scope() from public, anon, authenticated; grant execute on function public.validate_business_diagnosis_references() to service_role; grant execute on function public.validate_business_opportunity_scope() to service_role; grant execute on function public.validate_business_recommendation_scope() to service_role; grant execute on function public.validate_business_priority_scope() to service_role;
